const {posts,books,portrait}=window.CONTENT;const all=[...books,...posts];const $=s=>document.querySelector(s);const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let saved;try{saved=JSON.parse(localStorage.getItem('do-reading')||'[]');if(!Array.isArray(saved))saved=[]}catch{saved=[]}let type='Alle',topic='Alle Themen',limit=12;const date=s=>new Date(s).toLocaleDateString('de-DE',{day:'numeric',month:'short',year:'numeric'});const openButton=(p,img=true)=>`<button class="image-button" data-open="${p.id}" aria-label="${esc(p.title)} lesen">${img?`<img src="${esc(p.image)}" alt="${esc(p.title)}" loading="lazy">`:esc(p.title)}</button>`;$('#portrait').src=portrait;$('#hero-books').innerHTML=[books[1],books[0]].map(b=>`<img class="hero-book" src="${esc(b.image)}" alt="${esc(b.title)}">`).join('');$('#latest').innerHTML=posts.slice(0,3).map(p=>`<article class="post-card">${openButton(p)}<div class="meta"><span>${esc(p.topic)}</span><span>${date(p.date)}</span></div><h3>${esc(p.title)}</h3><button class="read-link" data-open="${p.id}">Weiterlesen ↗</button></article>`).join('');const topics=['Alle Themen','Bildung & Wandel','Selbsterkenntnis','Achtsamkeit','Denken & Medien'];$('#topics').innerHTML=topics.map((t,i)=>`<button data-topic="${esc(t)}" class="${i?'':'active'}" aria-pressed="${!i}">${esc(t)}</button>`).join('');
function render(){let q=$('#search').value.toLocaleLowerCase('de').trim();let items=all.filter(p=>(type==='Alle'||(type==='Merkliste'?saved.includes(p.id):p.type===type))&&(topic==='Alle Themen'||p.topic===topic)&&(!q||`${p.title} ${p.excerpt} ${p.topic} ${p.content.replace(/<[^>]+>/g,' ')}`.toLocaleLowerCase('de').includes(q)));if($('#sort').value==='az')items.sort((a,b)=>a.title.localeCompare(b.title,'de'));else items.sort((a,b)=>a.type===b.type?(b.date||'').localeCompare(a.date||''):a.type==='Buch'?-1:1);$('#results').textContent=`${items.length} ${items.length===1?'Entdeckung':'Entdeckungen'}${q?' für „'+$('#search').value+'“':''}`;$('#saved-count').textContent=saved.length;$('#catalog').innerHTML=items.slice(0,limit).map(p=>`<article class="catalog-card"><div class="cover ${p.type==='Artikel'?'article':''}">${openButton(p)}<button class="save" data-save="${p.id}" aria-pressed="${saved.includes(p.id)}" aria-label="${esc(p.title)} ${saved.includes(p.id)?'aus Merkliste entfernen':'merken'}">${saved.includes(p.id)?'♥':'♡'}</button></div><div class="meta"><span>${p.type} · ${esc(p.topic)}</span>${p.date?`<span>${new Date(p.date).getFullYear()}</span>`:''}</div><h3>${esc(p.title)}</h3><p class="excerpt">${esc(p.excerpt)}</p><button class="read-link" data-open="${p.id}">${p.type==='Buch'?'Buch entdecken':'Artikel lesen'} ↗</button></article>`).join('')||'<div class="empty"><h3>Noch nichts gefunden?</h3><p>Versuche einen anderen Suchbegriff oder wähle ein anderes Thema.</p><button class="button outline" data-reset>Filter zurücksetzen</button></div>';$('#more').hidden=items.length<=limit;}
function selectType(t){type=t;limit=12;document.querySelectorAll('[data-type]').forEach(b=>{b.classList.toggle('active',b.dataset.type===type);b.setAttribute('aria-pressed',b.dataset.type===type)});render()}
function openReader(id){const p=all.find(x=>x.id===id);if(!p)return;$('#reader-content').innerHTML=`<p class="eyebrow">${p.type} · ${esc(p.topic)}</p><h1>${esc(p.title)}</h1>${p.date?`<p>${date(p.date)} · Heidrun Drescher-Ochoa</p>`:''}<img class="reader-cover" src="${esc(p.image)}" alt="${esc(p.title)}"><div class="article-body">${p.content}</div><div class="reader-source"><a href="${esc(p.source)}" target="_blank" rel="noopener">${p.type==='Buch'?'Veröffentlichung auf der Originalwebsite ansehen':'Originalartikel ansehen'} ↗</a> · <button class="read-link" data-save="${p.id}">${saved.includes(p.id)?'♥ Gemerkt':'♡ Für später merken'}</button></div>`;$('#reader').showModal();$('#reader').scrollTop=0;document.body.classList.add('modal-open');history.replaceState(null,'','#lesen-'+id)}
function closeReader(){$('#reader').close();document.body.classList.remove('modal-open');history.replaceState(null,'','#bibliothek')}
document.addEventListener('click',e=>{let b=e.target.closest('[data-open]');if(b){openReader(b.dataset.open);return}b=e.target.closest('[data-save]');if(b){let id=b.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('do-reading',JSON.stringify(saved))}catch{}render();if(b.closest('#reader-content')){b.textContent=saved.includes(id)?'♥ Gemerkt':'♡ Für später merken'}return}b=e.target.closest('[data-type]');if(b)selectType(b.dataset.type);b=e.target.closest('[data-topic]');if(b){topic=b.dataset.topic;limit=12;document.querySelectorAll('[data-topic]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});render()}if(e.target.closest('[data-go-articles]'))selectType('Artikel');if(e.target.closest('[data-reset]')){$('#search').value='';topic='Alle Themen';document.querySelector('[data-topic="Alle Themen"]').click();selectType('Alle')}});$('#search').addEventListener('input',()=>{limit=12;render()});$('#sort').addEventListener('change',render);$('#more').onclick=()=>{limit+=12;render()};$('#reader-close').onclick=closeReader;$('#reader-back').onclick=closeReader;$('#reader').addEventListener('cancel',e=>{e.preventDefault();closeReader()});$('#reader').addEventListener('click',e=>{if(e.target===$('#reader'))closeReader()});render();if(location.hash.startsWith('#lesen-'))openReader(location.hash.slice(7));
